/**
 * Nuxt のモジュール。useAgent の自動の import、許可の関数の登録、開発のときの中継を受け持つ。
 * @nuxt/kit を読み込まずに nuxt.options と hook だけで書く。
 * pnpm では利用者のプロジェクトから @nuxt/kit が見えないことがあり、省ける peer dependency にしておくため
 */
import { existsSync } from "node:fs";
import { isAbsolute, join, resolve } from "node:path";
import { resolveAgentDevUrl, resolveAgentRoutes } from "./frontend-config";

export type RouarNuxtOptions = {
	/**
	 * 許可の関数のファイル。h3 の event を受け取る関数を default で export する。
	 * `~/server/rouar-authorize` のように Nuxt の alias で書ける
	 */
	authorize?: string;
	/** エージェントの経路の接頭辞。省くと rouar.json の agent.routes を読み、なければ /agents */
	agentRoutes?: string[];
	/** 開発のときに、エージェントの経路を手元の Flue の開発のサーバーへ中継するか。既定は true */
	devProxy?: boolean;
	/** 中継先。省くと ROUAR_AGENT_DEV_URL、なければ http://localhost:5173 */
	devTarget?: string;
};

/** このモジュールが読み書きする Nuxt の設定の部分 */
type NuxtOptionsLike = {
	rootDir: string;
	srcDir: string;
	buildDir: string;
	dev: boolean;
	alias: Record<string, string>;
	plugins: (string | { src: string; mode?: "all" | "server" | "client" })[];
	build: {
		templates: {
			filename: string;
			write?: boolean;
			getContents: () => string;
		}[];
	};
	rouar?: RouarNuxtOptions;
};

type NitroConfigLike = {
	plugins?: string[];
	handlers?: { route: string; handler: string; method?: string }[];
	virtual?: Record<string, string | (() => string | Promise<string>)>;
	imports?: false | { imports?: { name: string; from: string }[] };
};

type ImportLike = { name: string; from: string };

export type NuxtLike = {
	options: NuxtOptionsLike;
	hook(name: "imports:extend", fn: (imports: ImportLike[]) => void): unknown;
	hook(name: "nitro:config", fn: (config: NitroConfigLike) => void): unknown;
};

const SCRIPT_EXTENSIONS = [".ts", ".mts", ".js", ".mjs"];

/** Nuxt の alias を当てて、許可の関数のファイルの絶対パスを決める。見つからなければ例外にする */
export function resolveAuthorizePath(
	path: string,
	options: Pick<NuxtOptionsLike, "rootDir" | "alias">,
): string {
	let resolved = path;
	const aliases = Object.keys(options.alias).sort(
		(a, b) => b.length - a.length,
	);
	for (const alias of aliases) {
		if (resolved === alias || resolved.startsWith(`${alias}/`)) {
			resolved = `${options.alias[alias]}${resolved.slice(alias.length)}`;
			break;
		}
	}
	if (!isAbsolute(resolved)) resolved = resolve(options.rootDir, resolved);
	const candidates = [
		resolved,
		...SCRIPT_EXTENSIONS.map((extension) => `${resolved}${extension}`),
		...SCRIPT_EXTENSIONS.map((extension) =>
			join(resolved, `index${extension}`),
		),
	];
	for (const candidate of candidates) {
		if (
			existsSync(candidate) &&
			SCRIPT_EXTENSIONS.some((extension) => candidate.endsWith(extension))
		) {
			return candidate;
		}
	}
	throw new Error(
		`[rouar] The authorize file ${JSON.stringify(path)} in nuxt.config was not found.`,
	);
}

function authorizePluginCode(authorizePath: string): string {
	return [
		'import { createEvent } from "h3";',
		'import { registerNuxtAuthorize } from "@rouar/sdk/nuxt/runtime";',
		`import authorize from ${JSON.stringify(authorizePath)};`,
		"export default function rouarAuthorize() {",
		"  registerNuxtAuthorize(authorize, createEvent);",
		"}",
		"",
	].join("\n");
}

function devProxyCode(
	target: string,
	authorizePath: string | undefined,
): string {
	return [
		'import { defineEventHandler, proxyRequest } from "h3";',
		'import { handleDevAgentRequest } from "@rouar/sdk/nuxt/runtime";',
		authorizePath
			? `import authorize from ${JSON.stringify(authorizePath)};`
			: "const authorize = undefined;",
		"export default defineEventHandler((event) =>",
		`  handleDevAgentRequest(event, { target: ${JSON.stringify(target)}, authorize, proxyRequest }),`,
		");",
		"",
	].join("\n");
}

function clientPluginCode(agentRoute: string): string {
	return [
		'import { defineNuxtPlugin } from "#app";',
		'import { configureAgentClient } from "@rouar/sdk/client";',
		"export default defineNuxtPlugin({",
		'  name: "rouar:client",',
		"  setup() {",
		`    configureAgentClient({ agentRoute: ${JSON.stringify(agentRoute)} });`,
		"  },",
		"});",
		"",
	].join("\n");
}

/** Nuxt のモジュールの本体。nuxt.config の modules に "@rouar/sdk/nuxt" を書くと呼ばれる */
function rouarNuxtModule(
	inlineOptions: RouarNuxtOptions | undefined,
	nuxt: NuxtLike,
): void {
	const options: RouarNuxtOptions = {
		...nuxt.options.rouar,
		...inlineOptions,
	};
	const routes = resolveAgentRoutes(nuxt.options.rootDir, options.agentRoutes);
	const agentRoute = routes[0] as string;
	const authorizePath = options.authorize
		? resolveAuthorizePath(options.authorize, nuxt.options)
		: undefined;
	const devProxy = nuxt.options.dev && options.devProxy !== false;
	const devTarget = devProxy
		? resolveAgentDevUrl(
				options.devTarget
					? { ROUAR_AGENT_DEV_URL: options.devTarget }
					: process.env,
			)
		: undefined;

	nuxt.hook("imports:extend", (imports) => {
		imports.push({ name: "useAgent", from: "@rouar/sdk/vue" });
	});

	// 会話の URL の接頭辞を、ブラウザとサーバーの描画の両方で使えるように入れる
	const clientFile = "rouar-client.mjs";
	nuxt.options.build.templates.push({
		filename: clientFile,
		write: true,
		getContents: () => clientPluginCode(agentRoute),
	});
	nuxt.options.plugins.unshift({
		src: join(nuxt.options.buildDir, clientFile),
	});

	nuxt.hook("nitro:config", (config) => {
		// Nitro の virtual は絶対パスの鍵でも引けるので、ファイルを書かずに plugins と handlers から指せる
		config.virtual ??= {};
		if (config.imports !== false) {
			config.imports ??= {};
			config.imports.imports ??= [];
			config.imports.imports.push({
				name: "defineRouarAuthorize",
				from: "@rouar/sdk/nuxt/runtime",
			});
		}
		if (authorizePath) {
			const pluginId = join(nuxt.options.buildDir, "rouar", "authorize.mjs");
			config.virtual[pluginId] = authorizePluginCode(authorizePath);
			config.plugins ??= [];
			config.plugins.push(pluginId);
		}
		if (devTarget) {
			const handlerId = join(nuxt.options.buildDir, "rouar", "dev-proxy.mjs");
			config.virtual[handlerId] = devProxyCode(devTarget, authorizePath);
			config.handlers ??= [];
			for (const route of routes) {
				config.handlers.push({ route, handler: handlerId });
				config.handlers.push({ route: `${route}/**`, handler: handlerId });
			}
		}
	});
}

rouarNuxtModule.getMeta = async () => ({
	name: "@rouar/sdk/nuxt",
	configKey: "rouar",
});

export default rouarNuxtModule;
